22	use crate::pipeline::HtmlAttributeMode;
23	use crate::react_types::{checker_prop_used, react_props_wanted};
24	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
25	use crate::types::semantic::{
26	    MergedProps, SemanticComponent, SemanticFallback, SemanticOutcome, SemanticProp, SemanticProvider, SemanticTarget,
27	    SourceChange, merge_semantic_props, unread_diagnostic,
28	};
29	
30	/// What one request of the checker made of a component: the component it found, if any, and what the checker said
31	/// about the request itself (an edit it was not told about, why a component kept its structural result). Both are the
32	/// answer, so a late answer and every request the cache serves it to carry both.
33	#[derive(Clone, Default)]
34	struct Answered {
35	    component: Option<Arc<SemanticComponent>>,
36	    diagnostics: Vec<Diagnostic>,
37	}
38	
39	/// What the checker said about one component at one version of its file, and the generation they belong to.
40	#[derive(Default)]
41	struct AnswerCache {
42	    /// Raised by every [`SemanticHook::invalidate`]; an answer asked for under an earlier one is not stored.
43	    generation: u64,
44	    answers: FxHashMap<(String, u64), Answered>,
45	}
46	
47	type Answers = Mutex<AnswerCache>;
48	
49	pub(crate) struct SemanticHook {
50	    provider: Arc<dyn SemanticProvider>,
51	    /// How long a request waits for the checker before it takes the structural answer.
52	    wait: Duration,
53	    answers: Arc<Answers>,
54	    /// Set once the checker has been reported unavailable, so a session says so once, not per component.
55	    warned: AtomicBool,
56	}
57	
58	impl SemanticHook {
59	    pub(crate) fn new(provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
60	        Self { provider, wait, answers: Arc::new(Mutex::new(AnswerCache::default())), warned: AtomicBool::new(false) }
61	    }
62	
63	    /// Forget every answer, refuse the ones still being waited for, and tell the checker what changed: a source file
64	    /// changed, and the checker's props for any component can depend on it. The next request of each component asks
65	    /// the checker again, after it has been told.
66	    pub(crate) fn invalidate(&self, change: SourceChange) {
67	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
68	        cache.generation += 1;
69	        cache.answers.clear();
70	        self.provider.changed(change);
71	    }
72	
73	    /// `answer` with the checker's props, when it has them.
74	    pub(crate) fn refine(&self, mut answer: ComponentAnswer, mode: HtmlAttributeMode) -> ComponentAnswer {
75	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
76	            let mut hasher = FxHasher::default();
77	            bytes.hash(&mut hasher);
78	            hasher.finish()
79	        });
80	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
81	        let generation = self.generation();
82	
83	        if let Some(cached) = cache_key.as_ref().and_then(|key| self.cached(key)) {
84	            answer.diagnostics.extend(cached.diagnostics);
85	            self.apply(&mut answer, cached.component.as_ref(), mode);
86	            return answer;
87	        }
88	
89	        let target = SemanticTarget {
90	            key: answer.key.clone(),
91	            file_path: answer.entry.file_path.clone(),
92	            display_name: answer.entry.display_name.clone(),
93	            exports: answer.entry.exports.clone(),
94	            described: answer
95	                .entry
96	                .props
97	                .values()
98	                .filter(|prop| !prop.description.is_empty())
99	                .map(|prop| prop.name.clone())
100	                .collect(),
101	            react_wanted: react_props_wanted(mode, &answer.entry.props),
102	        };
103	        let receiver = self.provider.request(vec![target]);
104	        match receiver.recv_timeout(self.wait) {
105	            Ok(outcome) => {
106	                let Read { answered, once } = read_outcome(&answer.key, outcome);
107	                for diagnostic in once {
108	                    if !self.warned.swap(true, Ordering::Relaxed) {
109	                        answer.diagnostics.push(diagnostic);
110	                    }
111	                }
112	                answer.diagnostics.extend(answered.diagnostics.iter().cloned());
113	                let component = answered.component.clone();
114	                if let Some(key) = cache_key {
115	                    self.store(key, generation, answered);
116	                }
117	                self.apply(&mut answer, component.as_ref(), mode);
118	            }
119	            Err(RecvTimeoutError::Timeout) => {
120	                self.keep_late_answer(receiver, &answer, cache_key, generation);
121	                let mut pending = Diagnostic::new(
122	                    DiagnosticSeverity::Info,
123	                    DiagnosticCode::SemanticBackend,
124	                    "the TypeScript checker has not answered yet; the structural props are used, and the checker's \
125	                     replace them on the next request",
126	                );
127	                pending.affects = vec![answer.key.clone()];
128	                answer.diagnostics.push(pending);
129	            }
130	            Err(RecvTimeoutError::Disconnected) => {
131	                let mut stopped = Diagnostic::new(
132	                    DiagnosticSeverity::Warning,
133	                    DiagnosticCode::SemanticBackend,
134	                    "the TypeScript checker stopped without answering; the structural props are used",
135	                );
136	                stopped.affects = vec![answer.key.clone()];
137	                answer.diagnostics.push(stopped);
138	            }
139	        }
140	        answer
141	    }
142	
143	    fn generation(&self) -> u64 {
144	        self.answers.lock().unwrap_or_else(PoisonError::into_inner).generation
145	    }
146	
147	    fn cached(&self, key: &(String, u64)) -> Option<Answered> {
148	        self.answers.lock().unwrap_or_else(PoisonError::into_inner).answers.get(key).cloned()
149	    }
150	
151	    fn store(&self, key: (String, u64), generation: u64, answered: Answered) {
152	        store(&self.answers, key, generation, answered);
153	    }
154	
155	    /// Waits for an answer that missed its budget on a thread of its own, so the next request finds it.
156	    fn keep_late_answer(
157	        &self,
158	        receiver: Receiver<SemanticOutcome>,
159	        answer: &ComponentAnswer,
160	        cache_key: Option<(String, u64)>,
161	        generation: u64,
162	    ) {
163	        let Some(key) = cache_key else { return };
164	        let answers = self.answers.clone();
165	        let asked = answer.key.clone();
166	        std::thread::Builder::new()
167	            .name("caliper-late-answer".to_string())
168	            .spawn(move || {
169	                if let Ok(outcome) = receiver.recv() {
170	                    store(&answers, key, generation, read_outcome(&asked, outcome).answered);
171	                }
172	            })
173	            .ok();
174	    }
175	
176	    fn apply(&self, answer: &mut ComponentAnswer, component: Option<&Arc<SemanticComponent>>, mode: HtmlAttributeMode) {
177	        let Some(component) = component else { return };
178	        let structural = answer.entry.props.clone();
179	        let used: Vec<&Arc<SemanticProp>> = component
180	            .props
181	            .iter()
182	            .filter(|prop| checker_prop_used(mode, &prop.name, prop.react_declared, &structural))
183	            .collect();
184	        // A degrade diagnostic names the component, not the prop, so it can only go once no structural prop is left
185	        // that it could be about: one the checker did not return keeps its structural type, opaque or not.
186	        let still_degraded = structural
187	            .iter()
188	            .any(|(name, prop)| prop.prop_type.holds_opaque() && !used.iter().any(|answered| answered.name == *name));
189	        let MergedProps { kept, unread } =
190	            merge_semantic_props(&mut answer.entry, used.into_iter(), &mut FxHashMap::default());
191	        if !still_degraded {
192	            // A structural diagnostic about a prop the checker now answers for would be stale.
193	            answer.diagnostics.retain(|diagnostic| {
194	                !matches!(
195	                    diagnostic.code,
196	                    DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
197	                )
198	            });
199	        }
200	        let mut provenance = Diagnostic::new(
201	            DiagnosticSeverity::Info,
202	            DiagnosticCode::SemanticBackend,
203	            match kept {
204	                0 => "1 component(s) resolved by the TypeScript checker".to_string(),
205	                kept => format!(
206	                    "1 component(s) resolved by the TypeScript checker; {kept} prop(s) it did not report keep their \
207	                     structural type"
208	                ),
209	            },
210	        );
211	        provenance.affects = vec![answer.key.clone()];
212	        answer.diagnostics.push(provenance);
213	        if unread > 0 {
214	            answer.diagnostics.push(unread_diagnostic(unread, vec![answer.key.clone()]));
215	        }
216	    }
217	}
218	
219	/// Keeps `answered` for `key` unless the cache was invalidated since the question was asked.
220	fn store(answers: &Answers, key: (String, u64), generation: u64, answered: Answered) {
221	    let mut cache = answers.lock().unwrap_or_else(PoisonError::into_inner);
222	    if cache.generation == generation {
223	        cache.answers.insert(key, answered);
224	    }
225	}
226	
227	/// An outcome read for the component asked about.
228	struct Read {
229	    /// What is kept for the next request: the component and what the checker said about the request, each diagnostic
230	    /// naming the component.
231	    answered: Answered,
232	    /// What an unavailable checker says, which a session says once and not per component, so it is not kept.
233	    once: Vec<Diagnostic>,
234	}
235	
236	/// The answer for the component whose output key is `asked`, and the diagnostics the request produced: a warning that
237	/// came with an answer (an edit the checker was not told about) is about this request, and its fallback's reason says
238	/// why the component kept its structural result. An answer or fallback for another key is not this component's.
239	fn read_outcome(asked: &str, outcome: SemanticOutcome) -> Read {
240	    let SemanticOutcome { components, fallbacks, diagnostics: reported } = outcome;
241	    // Only an outcome with no answer at all says the checker is unavailable.
242	    let unavailable = components.is_empty() && fallbacks.is_empty();
243	    let mut read = Read { answered: Answered::default(), once: Vec::new() };
244	    for mut diagnostic in reported {
245	        diagnostic.affects = vec![asked.to_owned()];
246	        if unavailable && diagnostic.severity == DiagnosticSeverity::Warning {
247	            read.once.push(diagnostic);
248	        } else {
249	            read.answered.diagnostics.push(diagnostic);
250	        }
251	    }
252	    for SemanticFallback { key, reason } in fallbacks {
253	        if key != asked {
254	            continue;
255	        }
256	        let mut info = Diagnostic::new(
257	            DiagnosticSeverity::Info,
258	            DiagnosticCode::SemanticBackend,
259	            format!("1 component(s) kept their structural result: {reason}"),
260	        );
261	        info.affects = vec![key];
262	        read.answered.diagnostics.push(info);
263	    }
264	    read.answered.component = components.into_iter().find(|found| found.key == asked).map(Arc::new);
265	    read
266	}
