155	/// A warm `tsc` that answers for the components it is asked about. Dropping it stops the process.
156	pub struct OnDemand {
157	    jobs: Option<UnboundedSender<Job>>,
158	    thread: Option<JoinHandle<()>>,
159	    /// Receives once when the worker has stopped `tsc` and is about to exit.
160	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
161	    shutdown_wait: Duration,
162	    gauges: Arc<Gauges>,
163	}
