295	struct Checker {
296	    supervisor: Option<Supervisor>,
297	    /// Compiler options read once from the tsconfig for the running process.
298	    options: Option<serde_json::Value>,
299	    restarts: u32,
300	    /// Requests the running process has answered.
301	    served: u32,
302	    /// Why the checker cannot be used for the rest of the session.
303	    down: Option<String>,
304	    gauges: Arc<Gauges>,
305	    /// The snapshot the last request was answered from, kept for the next.
306	    live: Option<Live>,
307	    /// Files announced as changed since `live` was brought up to date.
308	    told: FxHashSet<Utf8PathBuf>,
309	}
