342	impl Checker {
343	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
344	        if let Some(reason) = &self.down {
345	            return Err(reason.clone());
346	        }
347	        if self.supervisor.as_ref().is_some_and(|supervisor| !supervisor.is_alive()) {
348	            if let Some(dead) = self.supervisor.take() {
349	                dead.shutdown().await.ok();
350	            }
351	            self.options = None;
352	            self.live = None;
353	            self.told.clear();
354	            self.restarts += 1;
355	            if self.restarts > MAX_RESTARTS {
356	                return Err(self.stay_down("the checker kept crashing".to_string()));
357	            }
358	        }
359	        if self.supervisor.is_none() {
360	            let request = SemanticRequest {
361	                project_root: config.project_root.clone(),
362	                tsconfig: config.tsconfig.clone(),
363	                tsc_path: config.tsc_path.clone(),
364	                targets: Vec::new(),
365	                request_timeout: config.request_timeout,
366	                expected_versions: config.expected_versions,
367	                record_to: None,
368	                extra_env: config.extra_env.clone(),
369	                reverse_queries: false,
370	            };
371	            let started = supervisor_config(&request).map_err(|reason| self.stay_down(reason))?;
372	            let supervisor = match Supervisor::spawn(started).await {
373	                Ok(supervisor) => supervisor,
374	                Err(error) => return Err(self.stay_down(error.to_string())),
375	            };
376	            // Initialize the session and read the compiler options once; every request after builds only its program.
377	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
378	            match Rpc::prepare(&supervisor.client(), config.request_timeout, tsconfig).await {
379	                Ok(options) => self.options = Some(options),
380	                Err(error) => {
381	                    supervisor.shutdown().await.ok();
382	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
383	                }
384	            }
385	            self.supervisor = Some(supervisor);
386	        }
387	        Ok(())
388	    }
389	
390	    fn stay_down(&mut self, reason: String) -> String {
391	        self.down = Some(reason.clone());
392	        reason
393	    }
394	
395	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
396	        if let Err(reason) = self.ensure(config).await {
397	            return SemanticOutcome::unavailable(reason);
398	        }
399	        let Some(supervisor) = self.supervisor.as_ref() else {
400	            return SemanticOutcome::unavailable("the checker is not running");
401	        };
402	        let (client, process) = (supervisor.client(), supervisor.process_id());
403	        let mut request = SemanticRequest::new(config.project_root.clone(), targets);
404	        request.tsconfig = config.tsconfig.clone();
405	        request.tsc_path = config.tsc_path.clone();
406	        request.request_timeout = config.request_timeout;
407	        request.expected_versions = config.expected_versions;
408	        request.extra_env.clone_from(&config.extra_env);
409	        let roots = root_files(&request);
410	        if roots.is_empty() {
411	            return group_by_file(&request).0;
412	        }
413	        let answered = match self.snapshot_for(client, config.request_timeout, roots.clone()).await {
414	            Ok((rpc, warning)) => answer_on(&rpc, &request, &roots).await.map(|mut outcome| {
415	                outcome.diagnostics.extend(warning);
416	                outcome
417	            }),
418	            Err(error) => Err(error),
419	        };
420	        self.gauges.process.store(process.unwrap_or(0), Ordering::Relaxed);
421	        self.served += 1;
422	        match answered {
423	            Ok(outcome) => outcome,
424	            Err(error) => {
425	                self.forget().await;
426	                SemanticOutcome::unavailable(format!("the checker stopped answering: {error}"))
427	            }
428	        }
429	    }
430	
431	    /// The snapshot to answer from, its program rooted at `roots`: the kept one brought up to date with the files the
432	    /// checker was told about, or a fresh one when none is kept, the kept one cannot be checked or updated, or a file
433	    /// it read changed with nobody telling the checker. The last comes with a warning that names the files.
434	    async fn snapshot_for(
435	        &mut self,
436	        client: Client,
437	        deadline: Duration,
438	        roots: Vec<String>,
439	    ) -> Result<(Arc<Rpc>, Option<Diagnostic>), CallError> {
440	        let read_from = SystemTime::now();
441	        let told = std::mem::take(&mut self.told);
442	        let mut warning = None;
443	        if let Some(live) = self.live.take() {
444	            if let Some(stamps) = &live.stamps {
445	                let drift = stamps::drift(stamps, &told);
446	                if drift.untold.is_empty() {
447	                    let reread: BTreeSet<Utf8PathBuf> = told.into_iter().chain(drift.unsure).collect();
448	                    if reread.is_empty() && live.roots == roots {
449	                        let rpc = live.rpc.clone();
450	                        self.live = Some(live);
451	                        return Ok((rpc, None));
452	                    }
453	                    let (changed, deleted): (Vec<String>, Vec<String>) = {
454	                        let (present, gone): (Vec<_>, Vec<_>) = reread.into_iter().partition(|file| file.exists());
455	                        (present.into_iter().map(String::from).collect(), gone.into_iter().map(String::from).collect())
456	                    };
457	                    let rerooted = (live.roots != roots).then_some(roots.as_slice());
458	                    match live.rpc.updated(&changed, &deleted, rerooted).await {
459	                        Ok(rpc) => {
460	                            live.rpc.release().await;
461	                            let rpc = Arc::new(rpc);
462	                            self.gauges.updated.fetch_add(1, Ordering::Relaxed);
463	                            self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
464	                            return Ok((rpc, None));
465	                        }
466	                        Err(CallError::Rejected(message)) => {
467	                            tracing::debug!(%message, "the checker could not update its snapshot; building a fresh one");
468	                        }
469	                        Err(fatal) => return Err(fatal),
470	                    }
471	                } else {
472	                    tracing::warn!(files = ?drift.untold, "files changed that the checker was not told about");
473	                    warning = Some(untold_warning(&drift.untold));
474	                }
475	            }
476	            live.rpc.release().await;
477	        }
478	        let options = self.options.as_ref().ok_or_else(|| CallError::Fatal("the checker is not initialized".into()))?;
479	        let rpc = Arc::new(Rpc::open_with(client, deadline, options, &roots, false).await?);
480	        self.gauges.created.fetch_add(1, Ordering::Relaxed);
481	        self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
482	        Ok((rpc, warning))
483	    }
484	
485	    /// Files changed on disk: the kept snapshot reads them again at the next request, or, when anything may have
486	    /// changed, is dropped.
487	    async fn told(&mut self, change: SourceChange) {
488	        match change {
489	            SourceChange::Files(files) if self.live.is_some() => self.told.extend(files),
490	            SourceChange::Files(_) => {}
491	            SourceChange::Everything => self.forget().await,
492	        }
493	    }
494	
495	    /// Drops the kept snapshot, so the next request builds one from the disk.
496	    async fn forget(&mut self) {
497	        self.told.clear();
498	        if let Some(live) = self.live.take() {
499	            live.rpc.release().await;
500	        }
501	    }
502	
503	    /// Lists and stamps the files the kept snapshot's program read, once, after the reply it answered, so the first
504	    /// answer does not wait for it. A snapshot that cannot be listed cannot be checked, and is dropped.
505	    async fn stamp(&mut self) {
506	        let Some(live) = self.live.as_mut().filter(|live| live.stamps.is_none()) else { return };
507	        match live.rpc.source_file_names().await {
508	            Ok(files) => {
509	                live.stamps = Some(stamps::record(files.into_iter().map(Utf8PathBuf::from).collect(), live.read_from))
510	            }
511	            Err(error) => {
512	                tracing::debug!(%error, "could not list the snapshot's files; the next request builds a fresh one");
513	                self.forget().await;
514	            }
515	        }
516	    }
517	
518	    /// Replaces the process when it has built enough programs or grown past the memory bound, and otherwise stamps
519	    /// the snapshot it keeps. A planned replacement, not a crash: the next request starts a fresh process.
520	    async fn maintain(&mut self, config: &OnDemandConfig) {
521	        let Some(supervisor) = self.supervisor.as_ref() else { return };
522	        let worn = self.served >= MAX_REQUESTS_PER_PROCESS;
523	        let resident = (!worn && self.served.is_multiple_of(RSS_CHECK_EVERY))
524	            .then(|| supervisor.process_id().and_then(resident_mib))
525	            .flatten();
526	        let bloated = resident.is_some_and(|mib| mib > config.max_rss_mib);
527	        if worn || bloated {
528	            let (count, cause) = if worn { (&self.gauges.worn, "worn") } else { (&self.gauges.bloated, "bloated") };
529	            count.fetch_add(1, Ordering::Relaxed);
530	            tracing::debug!(cause, served = self.served, resident_mib = ?resident, "replacing the checker process");
531	            // The snapshot goes with the process; the next one reads every file from the disk.
532	            self.live = None;
533	            self.told.clear();
534	            if let Some(old) = self.supervisor.take() {
535	                old.shutdown().await.ok();
536	            }
537	            self.options = None;
538	            self.served = 0;
539	            return;
540	        }
541	        self.stamp().await;
542	    }
543	}
