38	/// Crashes the checker may have before it stays down for the session.
39	const MAX_RESTARTS: u32 = 3;
40	
41	/// Programs one `tsc` process builds before it is replaced. Its memory grows with every program it has loaded
42	/// (measured: antd reached 600 MiB after 50 single-component programs), and a fresh process costs 30 to 70 ms.
43	const MAX_REQUESTS_PER_PROCESS: u32 = 64;
44	
45	/// Resident memory, in MiB, past which a `tsc` process is replaced between requests. Measured single-component programs
46	/// peak at 157 to 612 MiB (antd the highest); a process past this has loaded more than a story session needs.
47	const DEFAULT_MAX_RSS_MIB: u64 = 768;
48	
49	/// How many requests pass between memory checks: each reads the process table, which costs a few milliseconds.
50	const RSS_CHECK_EVERY: u32 = 4;
51	
52	/// How long dropping a checker waits, by default, for its worker to finish a request and stop `tsc`, before leaving the
53	/// worker to finish on its own. Closing a session must not wait for a 60 s request.
54	const DEFAULT_SHUTDOWN_WAIT: Duration = Duration::from_secs(5);
