96	/// The resident memory of a process in MiB: `/proc` where it exists, else `ps`. `None` when neither answers.
97	fn resident_mib(pid: u32) -> Option<u64> {
98	    let kib = match std::fs::read_to_string(format!("/proc/{pid}/status")) {
99	        Ok(status) => status
100	            .lines()
101	            .find_map(|line| line.strip_prefix("VmRSS:"))?
102	            .split_whitespace()
103	            .next()?
104	            .parse::<u64>()
105	            .ok()?,
106	        Err(_) => {
107	            let output = std::process::Command::new("ps").args(["-o", "rss=", "-p", &pid.to_string()]).output().ok()?;
108	            String::from_utf8_lossy(&output.stdout).trim().parse::<u64>().ok()?
109	        }
110	    };
111	    Some(kib / 1024)
112	}
