144	enum Job {
145	    /// Start the checker now instead of at the first request.
146	    Warm,
147	    /// Files changed on disk; queued before any request that may read them.
148	    Changed(SourceChange),
149	    Answer {
150	        targets: Vec<SemanticTarget>,
151	        reply: mpsc::SyncSender<SemanticOutcome>,
152	    },
153	}
