165	impl OnDemand {
166	    /// Starts the worker thread. The `tsc` process itself starts on the first request, or on [`OnDemand::warm_up`].
167	    pub fn new(config: OnDemandConfig) -> Self {
168	        let shutdown_wait = config.shutdown_wait;
169	        let (jobs, queue) = unbounded_channel();
170	        let (stopped_tx, stopped) = mpsc::channel();
171	        let gauges = Arc::new(Gauges::default());
172	        let worker_gauges = Arc::clone(&gauges);
173	        let thread = std::thread::Builder::new()
174	            .name("caliper-tsc".to_string())
175	            .spawn(move || {
176	                worker(config, queue, worker_gauges);
177	                stopped_tx.send(()).ok();
178	            })
179	            .ok();
180	        Self {
181	            jobs: thread.as_ref().map(|_| jobs),
182	            thread,
183	            stopped: std::sync::Mutex::new(Some(stopped)),
184	            shutdown_wait,
185	            gauges,
186	        }
187	    }
188	
189	    /// How many times the process has been replaced so far, by cause. A replacement happens after the reply it
190	    /// follows, so read this after the next request to see the last one.
191	    pub fn recycles(&self) -> Recycles {
192	        Recycles {
193	            worn: self.gauges.worn.load(Ordering::Relaxed),
194	            bloated: self.gauges.bloated.load(Ordering::Relaxed),
195	        }
196	    }
197	
198	    /// How many snapshots the answers so far came from, by how each was made.
199	    pub fn snapshots(&self) -> Snapshots {
200	        Snapshots {
201	            created: self.gauges.created.load(Ordering::Relaxed),
202	            updated: self.gauges.updated.load(Ordering::Relaxed),
203	        }
204	    }
205	
206	    /// The operating system's id of the `tsc` process that answered the last request, `None` before the first one.
207	    /// Read after a reply, it is the process that built that answer.
208	    pub fn process_id(&self) -> Option<u32> {
209	        Some(self.gauges.process.load(Ordering::Relaxed)).filter(|pid| *pid != 0)
210	    }
211	
212	    /// Starts `tsc` in the background so the first request does not pay for it.
213	    pub fn warm_up(&self) {
214	        if let Some(jobs) = &self.jobs {
215	            jobs.send(Job::Warm).ok();
216	        }
217	    }
218	}
