220	impl SemanticProvider for OnDemand {
221	    fn request(&self, targets: Vec<SemanticTarget>) -> mpsc::Receiver<SemanticOutcome> {
222	        let (reply, receiver) = mpsc::sync_channel(1);
223	        match &self.jobs {
224	            Some(jobs) => {
225	                if let Err(refused) = jobs.send(Job::Answer { targets, reply })
226	                    && let Job::Answer { reply, .. } = refused.0
227	                {
228	                    reply.send(SemanticOutcome::unavailable("the checker thread has stopped")).ok();
229	                }
230	            }
231	            None => {
232	                reply.send(SemanticOutcome::unavailable("could not start the checker thread")).ok();
233	            }
234	        }
235	        receiver
236	    }
237	
238	    fn changed(&self, change: SourceChange) {
239	        if let Some(jobs) = &self.jobs {
240	            jobs.send(Job::Changed(change)).ok();
241	        }
242	    }
243	}
