245	impl Drop for OnDemand {
246	    fn drop(&mut self) {
247	        // Closing the queue ends the worker loop, which shuts `tsc` down before the thread exits. A worker still inside
248	        // a long request is left to finish it: `tsc` stops when it does, or with this process.
249	        self.jobs.take();
250	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
251	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
252	        if let Some(thread) = self.thread.take()
253	            && stopped
254	        {
255	            thread.join().ok();
256	        }
257	    }
258	}
259	
260	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>, gauges: Arc<Gauges>) {
261	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
262	        Ok(runtime) => runtime,
263	        Err(error) => {
264	            let reason = format!("could not start an async runtime: {error}");
265	            while let Some(job) = queue.blocking_recv() {
266	                if let Job::Answer { reply, .. } = job {
267	                    reply.send(SemanticOutcome::unavailable(reason.clone())).ok();
268	                }
269	            }
270	            return;
271	        }
272	    };
273	    runtime.block_on(async move {
274	        let mut checker = Checker { gauges, ..Checker::default() };
275	        while let Some(job) = queue.recv().await {
276	            match job {
277	                Job::Warm => {
278	                    checker.ensure(&config).await.ok();
279	                }
280	                Job::Changed(change) => checker.told(change).await,
281	                Job::Answer { targets, reply } => {
282	                    reply.send(checker.answer(&config, targets).await).ok();
283	                    // After the reply, so the caller never waits for the memory check or the replacement.
284	                    checker.maintain(&config).await;
285	                }
286	            }
287	        }
288	        if let Some(supervisor) = checker.supervisor.take() {
289	            supervisor.shutdown().await.ok();
290	        }
291	    });
292	}
