383	        .filter_map(|part| part.split_once(':').map(|(name, _)| name.trim().to_string()))
384	        .collect();
385	    let version = format!("v{}", names.len());
386	    SemanticOutcome {
387	        components: vec![SemanticComponent {
388	            key: target.key.clone(),
389	            props: names
390	                .into_iter()
391	                .map(|name| {
392	                    Arc::new(SemanticProp {
393	                        name,
394	                        prop_type: PropType::StringLiteral(version.clone()),
395	                        required: false,
396	                        description: String::new(),
397	                        react_declared: false,
398	                    })
399	                })
400	                .collect(),
401	        }],
402	        ..SemanticOutcome::default()
403	    }
