568	/// The CLI merges the checker over a whole extraction; a session merges it over one component. They are two paths to
569	/// one answer, so what they agree on is pinned here and what they do not is pinned as the difference it is.
570	#[test]
571	fn the_whole_project_merge_and_the_session_merge_agree_on_every_prop_the_checker_answered() {
572	    let project = project(&[("Button.tsx", DEFAULTED)]);
573	    let options = PipelineOptions { src_dirs: vec![project.root.clone()], ..Default::default() };
574	
575	    let mut batch = caliper_docgen_core::extract(&options);
576	    let target = SemanticTarget {
577	        key: "Button".to_string(),
578	        file_path: batch.components["Button"].file_path.clone(),
579	        display_name: "Button".to_string(),
580	        exports: batch.components["Button"].exports.clone(),
581	        described: Default::default(),
582	        react_wanted: None,
583	    };
584	    caliper_docgen_core::types::semantic::merge_semantic(&mut batch, label_size_and_class_name(&target));
585	    let batch = &batch.components["Button"];
586	
587	    let session = session_in(&project, HtmlAttributeMode::Full, label_size_and_class_name);
588	    let on_demand = session.component("Button").unwrap().entry;
589	
590	    // What both agree on: the checker's type and optionality for a prop it answered, and the structural default.
591	    for name in ["label", "size"] {
592	        assert_eq!(batch.props[name], on_demand.props[name], "{name}");
593	    }
