595	    assert!(batch.props["label"].default_value.is_some(), "the structural default stays");
596	
597	    // Where they differ, on purpose: the whole-project merge lets the checker decide which props exist and leaves
598	    // `@types/react`'s to the inheritance layers; the session keeps a structural prop the checker did not return and
599	    // takes the `@types/react` prop its `htmlAttributes` mode lists.
600	    assert_eq!(batch.props.keys().cloned().collect::<Vec<_>>(), ["label", "size"]);
601	    assert_eq!(on_demand.props.keys().cloned().collect::<Vec<_>>(), ["className", "label", "legacy", "size"]);
