152	/// An empty session for `options`: lazy when they say so, with a checker attached when they ask for one.
153	fn new_session(options: JsExtractOptions) -> napi::Result<Arc<WatchSession>> {
154	    let lazy = options.lazy.unwrap_or(false);
155	    let semantic = match options.semantic_types.as_deref() {
156	        None | Some("off") => None,
157	        Some("on-demand") => Some((
158	            options.tsc_path.clone(),
159	            options.tsconfig_path.clone(),
160	            options.src_dirs.first().cloned(),
161	            options.semantic_wait_ms.unwrap_or(DEFAULT_SEMANTIC_WAIT_MS),
162	        )),
163	        Some(other) => {
164	            return Err(napi::Error::from_reason(format!("semanticTypes must be 'off' or 'on-demand', got '{other}'")));
165	        }
166	    };
167	    let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
168	    let session = match lazy {
169	        true => WatchSession::lazy(pipeline_options),
170	        false => WatchSession::new(pipeline_options),
171	    };
172	    let session = match semantic {
173	        Some((tsc_path, tsconfig, first_src, wait_ms)) => {
174	            let checker = on_demand_checker(tsc_path, tsconfig, first_src);
175	            session.with_semantic(checker, std::time::Duration::from_millis(u64::from(wait_ms)))
176	        }
177	        None => session,
178	    };
179	    Ok(Arc::new(session))
180	}
