213	
214	        let mut opts =
215	            PipelineOptions { src_dirs: js.src_dirs.into_iter().map(Into::into).collect(), ..Default::default() };
216	
217	        if let Some(exclude) = js.exclude {
218	            opts.exclude_patterns = exclude;
