221	            opts.html_attributes = caliper_docgen_core::pipeline::HtmlAttributeMode::parse(mode)
222	                .map_err(|bad| format!("htmlAttributes is '{bad}', expected \"curated\", \"full\" or \"none\""))?;
223	        }
