182	/// A warm `tsc` for the project that holds `first_src`. It starts in the background, so a request that arrives before
183	/// it is up takes the structural answer rather than waiting for the process.
184	fn on_demand_checker(
185	    tsc_path: Option<String>,
186	    tsconfig: Option<String>,
187	    first_src: Option<String>,
188	) -> Arc<caliper_docgen_semantic::OnDemand> {
189	    let root = first_src
190	        .as_deref()
191	        .and_then(|dir| caliper_docgen_core::canonical_path::canonicalize(camino::Utf8Path::new(dir)).ok())
192	        .or_else(|| std::env::current_dir().ok().and_then(|dir| camino::Utf8PathBuf::from_path_buf(dir).ok()))
193	        .unwrap_or_default();
194	    let mut config = caliper_docgen_semantic::OnDemandConfig::new(root.clone());
195	    config.tsconfig = tsconfig
196	        .map(camino::Utf8PathBuf::from)
197	        .or_else(|| root.ancestors().map(|dir| dir.join("tsconfig.json")).find(|file| file.is_file()));
198	    config.tsc_path = tsc_path.map(camino::Utf8PathBuf::from);
199	    let checker = caliper_docgen_semantic::OnDemand::new(config);
200	    checker.warm_up();
201	    Arc::new(checker)
202	}
