206	impl TryFrom<JsExtractOptions> for PipelineOptions {
207	    /// Names the bad `htmlAttributes` value — a typo (or a caller bypassing the TS union, e.g. via
208	    /// `as any`) must not silently fall back to a default (AGENTS.md non-negotiable #6).
209	    type Error = String;
210	
211	    fn try_from(js: JsExtractOptions) -> Result<Self, Self::Error> {
212	        use compact_str::CompactString;
213	
214	        let mut opts =
215	            PipelineOptions { src_dirs: js.src_dirs.into_iter().map(Into::into).collect(), ..Default::default() };
216	
217	        if let Some(exclude) = js.exclude {
218	            opts.exclude_patterns = exclude;
219	        }
220	        if let Some(mode) = js.html_attributes.as_deref() {
221	            opts.html_attributes = caliper_docgen_core::pipeline::HtmlAttributeMode::parse(mode)
222	                .map_err(|bad| format!("htmlAttributes is '{bad}', expected \"curated\", \"full\" or \"none\""))?;
223	        }
224	        if let Some(path) = js.tsconfig_path {
225	            opts.tsconfig_path = Some(path.into());
226	        }
227	        if let Some(names) = js.extra_builtins {
228	            opts.extra_builtins = names.into_iter().map(CompactString::from).collect();
229	        }
230	        if let Some(dir) = js.cache_dir {
231	            opts.cache_dir = Some(dir.into());
232	        }
233	        if let Some(cache) = js.cache {
234	            opts.use_cache = cache;
235	        }
236	        if let Some(load) = js.load_dependencies {
237	            opts.load_dependencies = load;
238	        }
239	        if let Some(mode) = js.collapse_inherited_props.as_deref() {
240	            opts.collapse_inherited_props = caliper_docgen_core::pipeline::CollapseInheritedProps::parse(mode)
241	                .map_err(|bad| {
242	                    format!("collapseInheritedProps is '{bad}', expected \"dependencies\", \"all\" or \"none\"")
243	                })?;
244	        }
245	
246	        Ok(opts)
247	    }
248	}
