408	/// The session's components with these keys as react-docgen-typescript documents them (`__docgenInfo`, which
409	/// Storybook converts to argTypes), as a JSON object keyed by component key. A key the session doesn't have is left
410	/// out; so is every key before the session is initialized. Errors for an unknown or closed session.
411	#[napi]
412	pub fn session_docgen_info(session_id: u32, keys: Vec<String>) -> napi::Result<String> {
413	    match caliper_docgen_core::panic_guard::contain_panic("session_docgen_info", move || {
414	        let session = live_session(session_id)?;
415	        let docs: serde_json::Map<String, serde_json::Value> = match session {
416	            // A lazy session resolves each requested component now, and the ones it already resolved are answered
417	            // from its memo.
418	            session if session.is_lazy() => {
419	                let answers = session.components(&keys);
420	                keys.into_iter()
421	                    .zip(answers)
422	                    .filter_map(|(key, answer)| {
423	                        Some((key, caliper_docgen_core::pipeline::rdt::docgen_info(&answer?.entry)))
424	                    })
425	                    .collect()
426	            }
427	            session => {
428	                let output = session.current_output();
429	                keys.into_iter()
430	                    .filter_map(|key| {
431	                        let entry = output.as_ref()?.components.get(&key)?;
432	                        Some((key, caliper_docgen_core::pipeline::rdt::docgen_info(entry)))
433	                    })
434	                    .collect()
435	            }
436	        };
437	        serde_json::to_string(&docs).map_err(|e| napi::Error::from_reason(e.to_string()))
438	    }) {
439	        Ok(result) => result,
440	        Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
441	    }
442	}
