491	/// Resolves `count` components spread evenly over the session's keys, without returning them: a lazy session then
492	/// holds the dependency declarations and resolver memos that components share, so the first request a host answers
493	/// does not load them. Runs off the calling thread and returns how many components it resolved. An eager session, an
494	/// unknown session and a count of 0 resolve nothing.
495	#[napi]
496	pub async fn session_warm_up(session_id: u32, count: u32) -> napi::Result<u32> {
497	    tokio::task::spawn_blocking(move || {
498	        match caliper_docgen_core::panic_guard::contain_panic("session_warm_up", move || {
499	            let Some(session) = SESSIONS.get(&session_id).map(|session| session.clone()) else { return 0 };
500	            if !session.is_lazy() || count == 0 {
501	                return 0;
502	            }
503	            let keys = session.component_keys();
504	            let wanted = (count as usize).min(keys.len());
505	            let spread: Vec<String> = (0..wanted).filter_map(|n| keys.get(n * keys.len() / wanted).cloned()).collect();
506	            session.components(&spread).into_iter().flatten().count() as u32
507	        }) {
508	            Ok(resolved) => Ok(resolved),
509	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
510	        }
511	    })
512	    .await
513	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
514	}
