196	/// Stateful session for incremental watch-mode extraction.
197	///
198	/// The session holds one immutable `Revision` at a time. `update_file` builds the next revision from the current one
199	/// (re-parsing the changed file, re-resolving the components whose resolution read it) and publishes it with a single
200	/// atomic store, so a reader always sees one complete revision, never parts of two. Writers are serialized; readers
201	/// never wait on them.
202	///
203	/// A lazy session ([`WatchSession::lazy`], ADR 0016) parses and indexes every file and resolves a component only when
204	/// [`WatchSession::component`] asks for it; the rest of this API behaves as for an eager one.
205	pub struct WatchSession {
206	    /// The options the session was created with.
207	    pub options: PipelineOptions,
208	    current: ArcSwapOption<Revision>,
209	    writer: Mutex<Freshness>,
210	    lazy: bool,
211	    semantic: Option<super::semantic_hook::SemanticHook>,
212	}
