214	/// The options and mode of a session, not its revision: a revision holds every parsed file and resolved component, so
215	/// printing it would bury the question a `{:?}` asks, which session this is.
216	impl std::fmt::Debug for WatchSession {
217	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
218	        f.debug_struct("WatchSession")
219	            .field("options", &self.options)
220	            .field("lazy", &self.lazy)
221	            .field("revision", &self.revision())
222	            .field("with_semantic", &self.semantic.is_some())
223	            .finish_non_exhaustive()
224	    }
225	}
