254	    /// Attach a TypeScript checker that is asked for each component a request names (ADR 0022). [`Self::component`]
255	    /// then returns the checker's props when it answers within `wait`, the structural ones otherwise, and the checker's
256	    /// late answer on the next request of the same, unedited component. Without a checker nothing changes.
257	    #[must_use]
258	    pub fn with_semantic(mut self, provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
