export function expandDiagnostics(diagnostics: WireDiagnostic[], nameLists: Record<string, string[]>): Diagnostic[] {
  return diagnostics.map(({ affects, ...rest }) => {
    if (affects === undefined) return rest
    const names = nameLists[affects]
