1	//! Scratch measurements for "how fast do a story's checker props arrive" (ADR 0026 S4/S8). Not part of the repo.
2	//!
3	//!   storyprops cold     --src DIR --tsc PATH --key K [--runs 5] [--wait-ms 120000]
4	//!   storyprops percomp  --src DIR --tsc PATH --keys A,B,C [--runs 3]
5	//!   storyprops batch    --src DIR --tsc PATH --keys A,B,C [--runs 3]
6	//!   storyprops prefetch --src DIR --tsc PATH --prefetch A,B,C --story S --gap-ms G [--runs 3]
7	//!   storyprops sizes    --src DIR --tsc PATH [--every 20]
8	use std::process::Command;
9	use std::sync::Arc;
10	use std::time::{Duration, Instant};
11	
12	use caliper_docgen_core::pipeline::{CollapseInheritedProps, ComponentAnswer, PipelineOptions, WatchSession};
13	use caliper_docgen_core::react_types::react_props_wanted;
14	use caliper_docgen_core::types::semantic::{SemanticProvider, SemanticTarget};
15	use caliper_docgen_semantic::{OnDemand, OnDemandConfig};
16	use camino::Utf8PathBuf;
17	
18	const CHECKER_NOTE: &str = "resolved by the TypeScript checker";
19	
20	fn arg(args: &[String], name: &str) -> Option<String> {
21	    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
22	}
23	
24	fn options(src: &Utf8PathBuf) -> PipelineOptions {
25	    PipelineOptions {
26	        src_dirs: vec![src.clone()],
27	        load_dependencies: true,
28	        collapse_inherited_props: CollapseInheritedProps::None,
29	        ..PipelineOptions::default()
30	    }
31	}
32	
33	/// As the binding's `new_session` + `on_demand_checker`: the checker is started in the background at creation.
34	fn open(src: &Utf8PathBuf, tsc: &str, tsconfig: Option<Utf8PathBuf>, wait: Duration) -> (WatchSession, Arc<OnDemand>) {
35	    let mut config = OnDemandConfig::new(src.clone());
36	    config.tsconfig = tsconfig.or_else(|| src.ancestors().map(|dir| dir.join("tsconfig.json")).find(|f| f.is_file()));
37	    config.tsc_path = Some(Utf8PathBuf::from(tsc));
38	    config.request_timeout = Duration::from_secs(120);
39	    let checker = OnDemand::new(config);
40	    checker.warm_up();
41	    let checker = Arc::new(checker);
42	    let session = WatchSession::lazy(options(src)).with_semantic(checker.clone(), wait);
43	    (session, checker)
44	}
45	
46	fn by_checker(answer: &ComponentAnswer) -> bool {
47	    answer.diagnostics.iter().any(|d| d.message.contains(CHECKER_NOTE))
48	}
49	
50	fn rss_mib(pid: u32) -> u64 {
51	    Command::new("ps")
52	        .args(["-o", "rss=", "-p", &pid.to_string()])
53	        .output()
54	        .ok()
55	        .and_then(|o| String::from_utf8_lossy(&o.stdout).trim().parse::<u64>().ok())
56	        .map_or(0, |kib| kib / 1024)
57	}
58	
59	fn self_rss_mib() -> u64 {
60	    rss_mib(std::process::id())
61	}
62	
63	fn ms(since: Instant) -> f64 {
64	    since.elapsed().as_secs_f64() * 1000.0
65	}
66	
67	fn target_of(session: &WatchSession, answer: &ComponentAnswer) -> SemanticTarget {
68	    let entry = &answer.entry;
69	    SemanticTarget {
70	        key: answer.key.clone(),
71	        file_path: entry.file_path.clone(),
72	        display_name: entry.display_name.clone(),
73	        exports: entry.exports.clone(),
74	        described: entry.props.values().filter(|p| !p.description.is_empty()).map(|p| p.name.clone()).collect(),
75	        react_wanted: react_props_wanted(session.options.html_attributes, &entry.props),
76	    }
77	}
78	
79	/// Structural answers (no checker), to build targets from.
80	fn structural_targets(src: &Utf8PathBuf, keys: &[String]) -> (Vec<SemanticTarget>, Vec<usize>) {
81	    let plain = WatchSession::lazy(options(src));
82	    drop(plain.initialize());
83	    let answers: Vec<ComponentAnswer> = keys.iter().map(|k| plain.component(k).expect("a component")).collect();
84	    let counts = answers.iter().map(|a| a.entry.props.len()).collect();
85	    (answers.iter().map(|a| target_of(&plain, a)).collect(), counts)
86	}
87	
88	fn wait_until_up(checker: &OnDemand) {
89	    drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
90	}
91	
92	fn cold(src: &Utf8PathBuf, tsc: &str, key: &str, runs: usize, wait: Duration) {
93	    for run in 0..runs {
94	        let t0 = Instant::now();
95	        let (session, checker) = open(src, tsc, None, wait);
96	        drop(session.initialize());
97	        let init = ms(t0);
98	        let began = Instant::now();
99	        let answer = session.component(key).expect("a component");
100	        let first = ms(began);
101	        let total = ms(t0);
102	        // The process may still be starting if the structural answer came back first; wait, then ask again (cache).
103	        wait_until_up(&checker);
104	        let began = Instant::now();
105	        let again = session.component(key).expect("a component");
106	        let again_ms = ms(began);
107	        println!(
108	            "{{\"mode\":\"cold\",\"run\":{run},\"key\":{key:?},\"waitMs\":{},\"initMs\":{init:.1},\"componentMs\":{first:.1},\"sinceCreateMs\":{total:.1},\"byChecker\":{},\"props\":{},\"againMs\":{again_ms:.1},\"againByChecker\":{},\"tsrsMib\":{},\"selfMib\":{}}}",
109	            wait.as_millis(),
110	            by_checker(&answer),
111	            answer.entry.props.len(),
112	            by_checker(&again),
113	            checker.process_id().map_or(0, rss_mib),
114	            self_rss_mib(),
115	        );
116	    }
117	}
118	
119	fn percomp(src: &Utf8PathBuf, tsc: &str, keys: &[String], runs: usize) {
