//! Scratch measurements for "how fast do a story's checker props arrive" (ADR 0026 S4/S8). Not part of the repo.
//!
//!   storyprops cold     --src DIR --tsc PATH --key K [--runs 5] [--wait-ms 120000]
//!   storyprops percomp  --src DIR --tsc PATH --keys A,B,C [--runs 3]
//!   storyprops batch    --src DIR --tsc PATH --keys A,B,C [--runs 3]
//!   storyprops prefetch --src DIR --tsc PATH --prefetch A,B,C --story S --gap-ms G [--runs 3]
//!   storyprops sizes    --src DIR --tsc PATH [--every 20]
use std::process::Command;
use std::sync::Arc;
use std::time::{Duration, Instant};

use caliper_docgen_core::pipeline::{CollapseInheritedProps, ComponentAnswer, PipelineOptions, WatchSession};
use caliper_docgen_core::react_types::react_props_wanted;
use caliper_docgen_core::types::semantic::{SemanticProvider, SemanticTarget};
use caliper_docgen_semantic::{OnDemand, OnDemandConfig};
use camino::Utf8PathBuf;

const CHECKER_NOTE: &str = "resolved by the TypeScript checker";

fn arg(args: &[String], name: &str) -> Option<String> {
    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
}

fn options(src: &Utf8PathBuf) -> PipelineOptions {
    PipelineOptions {
        src_dirs: vec![src.clone()],
        load_dependencies: true,
        collapse_inherited_props: CollapseInheritedProps::None,
        ..PipelineOptions::default()
    }
}

/// As the binding's `new_session` + `on_demand_checker`: the checker is started in the background at creation.
fn open(src: &Utf8PathBuf, tsc: &str, tsconfig: Option<Utf8PathBuf>, wait: Duration) -> (WatchSession, Arc<OnDemand>) {
    let mut config = OnDemandConfig::new(src.clone());
    config.tsconfig = tsconfig.or_else(|| src.ancestors().map(|dir| dir.join("tsconfig.json")).find(|f| f.is_file()));
    config.tsc_path = Some(Utf8PathBuf::from(tsc));
    config.request_timeout = Duration::from_secs(120);
    let checker = OnDemand::new(config);
    checker.warm_up();
    let checker = Arc::new(checker);
    let session = WatchSession::lazy(options(src)).with_semantic(checker.clone(), wait);
    (session, checker)
}

fn by_checker(answer: &ComponentAnswer) -> bool {
    answer.diagnostics.iter().any(|d| d.message.contains(CHECKER_NOTE))
}

fn rss_mib(pid: u32) -> u64 {
    Command::new("ps")
        .args(["-o", "rss=", "-p", &pid.to_string()])
        .output()
        .ok()
        .and_then(|o| String::from_utf8_lossy(&o.stdout).trim().parse::<u64>().ok())
        .map_or(0, |kib| kib / 1024)
}

fn self_rss_mib() -> u64 {
    rss_mib(std::process::id())
}

fn ms(since: Instant) -> f64 {
    since.elapsed().as_secs_f64() * 1000.0
}

fn target_of(session: &WatchSession, answer: &ComponentAnswer) -> SemanticTarget {
    let entry = &answer.entry;
    SemanticTarget {
        key: answer.key.clone(),
        file_path: entry.file_path.clone(),
        display_name: entry.display_name.clone(),
        exports: entry.exports.clone(),
        described: entry.props.values().filter(|p| !p.description.is_empty()).map(|p| p.name.clone()).collect(),
        react_wanted: react_props_wanted(session.options.html_attributes, &entry.props),
    }
}

/// Structural answers (no checker), to build targets from.
fn structural_targets(src: &Utf8PathBuf, keys: &[String]) -> (Vec<SemanticTarget>, Vec<usize>) {
    let plain = WatchSession::lazy(options(src));
    drop(plain.initialize());
    let answers: Vec<ComponentAnswer> = keys.iter().map(|k| plain.component(k).expect("a component")).collect();
    let counts = answers.iter().map(|a| a.entry.props.len()).collect();
    (answers.iter().map(|a| target_of(&plain, a)).collect(), counts)
}

fn wait_until_up(checker: &OnDemand) {
    drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
}

fn cold(src: &Utf8PathBuf, tsc: &str, key: &str, runs: usize, wait: Duration) {
    for run in 0..runs {
        let t0 = Instant::now();
        let (session, checker) = open(src, tsc, None, wait);
        drop(session.initialize());
        let init = ms(t0);
        let began = Instant::now();
        let answer = session.component(key).expect("a component");
        let first = ms(began);
        let total = ms(t0);
        // The process may still be starting if the structural answer came back first; wait, then ask again (cache).
        wait_until_up(&checker);
        let began = Instant::now();
        let again = session.component(key).expect("a component");
        let again_ms = ms(began);
        println!(
            "{{\"mode\":\"cold\",\"run\":{run},\"key\":{key:?},\"waitMs\":{},\"initMs\":{init:.1},\"componentMs\":{first:.1},\"sinceCreateMs\":{total:.1},\"byChecker\":{},\"props\":{},\"againMs\":{again_ms:.1},\"againByChecker\":{},\"tsrsMib\":{},\"selfMib\":{}}}",
            wait.as_millis(),
            by_checker(&answer),
            answer.entry.props.len(),
            by_checker(&again),
            checker.process_id().map_or(0, rss_mib),
            self_rss_mib(),
        );
    }
}

fn percomp(src: &Utf8PathBuf, tsc: &str, keys: &[String], runs: usize) {
    let (targets, structural_counts) = structural_targets(src, keys);
    for run in 0..runs {
        let t0 = Instant::now();
        let (session, checker) = open(src, tsc, None, Duration::from_secs(120));
        drop(session.initialize());
        let init = ms(t0);
        wait_until_up(&checker);
        let up = ms(t0);
        let mut rows = Vec::new();
        for (i, key) in keys.iter().enumerate() {
            let began = Instant::now();
            let answer = session.component(key).expect("a component");
            let first = ms(began);
            // Same request again straight to the checker: same roots, the kept snapshot, a fresh converter.
            let began = Instant::now();
            drop(checker.request(vec![targets[i].clone()]).recv_timeout(Duration::from_secs(120)));
            let again = ms(began);
            // And through the session: the hook's cache.
            let began = Instant::now();
            drop(session.component(key));
            let cached = ms(began);
            rows.push(format!(
                "{{\"key\":{key:?},\"structuralProps\":{},\"props\":{},\"byChecker\":{},\"componentMs\":{first:.1},\"sameSnapshotRequestMs\":{again:.1},\"cachedMs\":{cached:.2}}}",
                structural_counts[i],
                answer.entry.props.len(),
                by_checker(&answer)
            ));
        }
        let snaps = checker.snapshots();
        println!(
            "{{\"mode\":\"percomp\",\"run\":{run},\"initMs\":{init:.1},\"processUpMs\":{up:.1},\"snapshots\":{{\"created\":{},\"updated\":{}}},\"tsrsMib\":{},\"selfMib\":{},\"components\":[{}]}}",
            snaps.created,
            snaps.updated,
            checker.process_id().map_or(0, rss_mib),
            self_rss_mib(),
            rows.join(",")
        );
    }
}

fn batch(src: &Utf8PathBuf, tsc: &str, keys: &[String], runs: usize) {
    let (targets, _) = structural_targets(src, keys);
    for run in 0..runs {
        let (_session, checker) = open(src, tsc, None, Duration::from_secs(120));
        wait_until_up(&checker);
        let began = Instant::now();
        let outcome = checker.request(targets.clone()).recv_timeout(Duration::from_secs(300)).expect("an answer");
        let all = ms(began);
        let rss = checker.process_id().map_or(0, rss_mib);
        println!(
            "{{\"mode\":\"batch\",\"run\":{run},\"components\":{},\"answered\":{},\"fallbacks\":{},\"batchMs\":{all:.1},\"perComponentMs\":{:.1},\"tsrsMib\":{rss},\"selfMib\":{}}}",
            keys.len(),
            outcome.components.len(),
            outcome.fallbacks.len(),
            all / keys.len() as f64,
            self_rss_mib(),
        );
    }
}

fn prefetch(src: &Utf8PathBuf, tsc: &str, keys: &[String], story: &str, gap: Duration, runs: usize) {
    for run in 0..runs {
        let t0 = Instant::now();
        let (session, checker) = open(src, tsc, None, Duration::from_secs(120));
        let session = Arc::new(session);
        drop(session.initialize());
        let init = ms(t0);
        let background = {
            let (session, keys) = (session.clone(), keys.to_vec());
            std::thread::spawn(move || {
                let answers = session.components(&keys);
                (ms(t0), answers.iter().flatten().filter(|a| by_checker(a)).count())
            })
        };
        if let Some(rest) = gap.checked_sub(t0.elapsed()) {
            std::thread::sleep(rest);
        }
        let asked = ms(t0);
        let began = Instant::now();
        let answer = session.component(story).expect("a component");
        let latency = ms(began);
        let (done, prefetched) = background.join().expect("prefetch thread");
        println!(
            "{{\"mode\":\"prefetch\",\"run\":{run},\"prefetch\":{},\"story\":{story:?},\"storyInPrefetch\":{},\"gapMs\":{},\"initMs\":{init:.1},\"askedAtMs\":{asked:.1},\"storyLatencyMs\":{latency:.1},\"storyByChecker\":{},\"prefetchDoneAtMs\":{done:.1},\"prefetchedByChecker\":{prefetched},\"tsrsMib\":{},\"selfMib\":{}}}",
            keys.len(),
            keys.iter().any(|k| k == story),
            gap.as_millis(),
            by_checker(&answer),
            checker.process_id().map_or(0, rss_mib),
            self_rss_mib(),
        );
    }
}

fn sizes(src: &Utf8PathBuf, tsc: &str, every: usize) {
    let (session, checker) = open(src, tsc, None, Duration::from_secs(120));
    drop(session.initialize());
    wait_until_up(&checker);
    let mut keys = session.component_keys();
    keys.sort();
    for key in keys.iter().step_by(every.max(1)) {
        let began = Instant::now();
        let Some(answer) = session.component(key) else { continue };
        println!(
            "{{\"mode\":\"sizes\",\"key\":{key:?},\"props\":{},\"byChecker\":{},\"ms\":{:.1}}}",
            answer.entry.props.len(),
            by_checker(&answer),
            ms(began)
        );
    }
}

fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .with_writer(std::io::stderr)
        .init();
    let args: Vec<String> = std::env::args().collect();
    let src = Utf8PathBuf::from(arg(&args, "--src").expect("--src"));
    let src = Utf8PathBuf::from_path_buf(std::fs::canonicalize(src).unwrap()).unwrap();
    let tsc = arg(&args, "--tsc").expect("--tsc");
    let runs = arg(&args, "--runs").map_or(3, |n| n.parse().unwrap());
    let list = |name: &str| -> Vec<String> {
        arg(&args, name).map(|v| v.split(',').map(str::to_string).collect()).unwrap_or_default()
    };
    match args.get(1).map(String::as_str) {
        Some("cold") => cold(
            &src,
            &tsc,
            &arg(&args, "--key").expect("--key"),
            runs,
            Duration::from_millis(arg(&args, "--wait-ms").map_or(120_000, |n| n.parse().unwrap())),
        ),
        Some("percomp") => percomp(&src, &tsc, &list("--keys"), runs),
        Some("batch") => batch(&src, &tsc, &list("--keys"), runs),
        Some("prefetch") => prefetch(
            &src,
            &tsc,
            &list("--prefetch"),
            &arg(&args, "--story").expect("--story"),
            Duration::from_millis(arg(&args, "--gap-ms").map_or(0, |n| n.parse().unwrap())),
            runs,
        ),
        Some("dump") => {
            let (session, checker) = open(&src, &tsc, None, Duration::from_secs(120));
            drop(session.initialize());
            wait_until_up(&checker);
            for key in list("--keys") {
                let began = Instant::now();
                let answer = session.component(&key).expect("a component");
                let took = ms(began);
                let text = format!("{}\n{:?}", serde_json::to_string(&answer.entry).unwrap(), answer.diagnostics);
                std::fs::write(format!("{}/{key}.txt", arg(&args, "--out").expect("--out")), &text).unwrap();
                println!("{{\"mode\":\"dump\",\"key\":{key:?},\"ms\":{took:.1},\"byChecker\":{},\"bytes\":{}}}", by_checker(&answer), text.len());
            }
        }
        Some("keys") => {
            let began = Instant::now();
            let plain = WatchSession::lazy(options(&src));
            drop(plain.initialize());
            let init = ms(began);
            let keys = plain.component_keys();
            let needle = arg(&args, "--grep").unwrap_or_default();
            println!("{{\"mode\":\"keys\",\"initMs\":{init:.1},\"count\":{}}}", keys.len());
            for key in keys.iter().filter(|k| k.contains(&needle)).take(40) {
                println!("{key}");
            }
        }
        Some("sizes") => sizes(&src, &tsc, arg(&args, "--every").map_or(20, |n| n.parse().unwrap())),
        _ => eprintln!("usage: see the module comment"),
    }
}

