    let receiver = self.request(targets);
    let delivery = Arc::new(Mutex::new(Some(delivery)));
    let take = |slot: &Mutex<Option<Delivery>>| slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
