1	//! Scratch measurements for "how fast do a story's checker props arrive" (ADR 0026 S4/S8). Not part of the repo.
2	//!
3	//!   storyprops cold     --src DIR --tsc PATH --key K [--runs 5] [--wait-ms 120000]
4	//!   storyprops percomp  --src DIR --tsc PATH --keys A,B,C [--runs 3]
5	//!   storyprops batch    --src DIR --tsc PATH --keys A,B,C [--runs 3]
6	//!   storyprops prefetch --src DIR --tsc PATH --prefetch A,B,C --story S --gap-ms G [--runs 3]
7	//!   storyprops sizes    --src DIR --tsc PATH [--every 20]
8	use std::process::Command;
9	use std::sync::Arc;
10	use std::time::{Duration, Instant};
11	
12	use caliper_docgen_core::pipeline::{CollapseInheritedProps, ComponentAnswer, PipelineOptions, WatchSession};
13	use caliper_docgen_core::react_types::react_props_wanted;
14	use caliper_docgen_core::types::semantic::{SemanticProvider, SemanticTarget};
15	use caliper_docgen_semantic::{OnDemand, OnDemandConfig};
16	use camino::Utf8PathBuf;
17	
18	const CHECKER_NOTE: &str = "resolved by the TypeScript checker";
19	
20	fn arg(args: &[String], name: &str) -> Option<String> {
21	    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
22	}
