24	fn options(src: &Utf8PathBuf) -> PipelineOptions {
25	    PipelineOptions {
26	        src_dirs: vec![src.clone()],
27	        load_dependencies: true,
28	        collapse_inherited_props: CollapseInheritedProps::None,
29	        ..PipelineOptions::default()
30	    }
31	}
